public class Complex_reciprocal_TriageGen1Test {

    private static final double EPSILON = 1e-10;





    @Test
    public void testReciprocal_IsInfinite() {
        // Test with real infinity
        Complex c1 = new Complex(Double.POSITIVE_INFINITY, 0.0);
        assertEquals("Reciprocal of infinity should be ZERO", Complex.ZERO, c1.reciprocal());

        // Test with imaginary infinity
        Complex c2 = new Complex(0.0, Double.NEGATIVE_INFINITY);
        assertEquals("Reciprocal of imaginary infinity should be ZERO", Complex.ZERO, c2.reciprocal());
    }








}

package org.apache.commons.math3.complex;

import java.io.*;
